```javascript
function quickSort(arr) {
    if (arr.length <= 1) return arr;

    let pivot = Math.floor(arr.length / 2);
    let left = [];
    let right = [];

    // 分配pivot到left或right数组
    arr.splice(pivot, 1);

    for (let element of arr) {
        if (element < arr[pivot]) {
            left.push(element);
        } else {
            right.push(element);
        }
    }

    return quickSort(left).concat(arr[pivot], quickSort(right));
}

// 示例用法
const unsortedArray = [10, 7, 8, 9, 1, 5];
console.log(quickSort(unsortedArray)); // 输出应为已排序的数组
```

