```javascript
function quickSort(arr) {
    // 判断数组长度是否小于或等于1，如果是则直接返回原数组（无进一步排序）
    if (arr.length <= 1) {
        return arr;
    }

    const pivot = arr.pop(); // 取出最后一个元素作为基准值

    // 使用filter方法分割数组，分割后的数组分为两个部分：
    // 左边的部分是小于等于基准的元素
    // 右边的部分是大于基准的元素
    let lessThanPivot = arr.filter(x => x <= pivot);
    let greaterThanPivot = arr.filter(x => x > pivot);

    // 递归地对左右两部分进行排序，并将它们与基准值重新合并返回
    return [...quickSort(lessThanPivot), pivot, ...quickSort(greaterThanPivot)];
}

// 测试快速排序函数
let unsortedArray = [34, -5897, 0, 24637, ..., 123]; // 填充实际数据或使用一个数组的实例如[5, 2, 8, 7, 4]
console.log(quickSort(unsortedArray));
```

这里的 `unsortedArray` 被填充为测试的实际数组。你可以将这个函数用于你的任何需要排序的数据集。

请注意，快速排序在最坏情况下（即每次分区时，较小部分与较大一部分的元素个数相同）的时间复杂度是 O(n^2)。通过使用随机化pivot或者其他优化策略可以显著提升性能，例如选择第一个元素、最后一个元素或一个随机元素作为`pivot`等。

